rowdata.pyStepsJavaSource:
// If creating an output page when all goes well isn't desired then we must
// clear it at the start, because callers will use @OperationFail() afterwards
// and we wouldn't want an incorrect result because of a page from a previous op.
if (tools.getParamValue("OutputPageName").equals(""))
   tools.putParamValue("OutputPageName", "pyOutput");
ClipboardPage op = tools.findPage(tools.getParamValue("OutputPageName"));
if (op != null)
{
   op.getProperty("pyStatus").clearValue();
   op.getProperty("pyErrors").removeFromClipboard();
}

// This activity was called with a primary page.  If the primary page
// has a computable handle and a name, we will discard the parameters
// assignPage and assignmentHandle.  If the primary page has a computable
// handle but no name, we will rename it according to assignPage parameter.  If the
// primary page has a name but no computable handle, we will preferentially
// use "newAssignPage" over its current name.

String primaryPageName = myStepPage.getName();
String primaryHandle = "";
try { primaryHandle = tools.getDatabase().getHandle(myStepPage); }
catch (DatabaseException e) { primaryHandle = ""; }
String assignPage = tools.getParamValue("assignPage");

if (primaryPageName.length() > 0 && primaryHandle.length() > 0)
{
	// We are going to use the primary page in preference over the other params
	tools.putParamValue("assignPage", primaryPageName);
	tools.putParamValue("assignmentHandle", primaryHandle);
	nextBlock = "Cont";
}
else if (primaryHandle.length() > 0)
{
	// We are going to use the primary page, but we need the assignPage name
	// passed in, if any, else default to newAssignPage
	if (assignPage.length() > 0)
		myStepPage.rename(assignPage);
	else
		myStepPage.rename("newAssignPage");

	// Set assignmentHandle to whatever the primary has
	tools.putParamValue("assignmentHandle", primaryHandle);
	nextBlock = "Cont";
}
else if (primaryPageName.length() > 0)
{
	// The primary page passed in doesn't even have a computable handle, so
	// it is most likely just some temp page.  Let's use the assignPage param
	if (assignPage.length() == 0)
		tools.putParamValue("assignPage", primaryPageName);
}

String strAssignHandle = tools.getParamValue("assignmentHandle");
if (strAssignHandle == null || strAssignHandle.equals(""))
{
	// We check for this earlier, so we won't get here, but I'll keep this in case the rule gets rearranged.
	errorMessage = "ProblemAssignment_MissingAssignmentHandle";
	status = pega_procom_processenginestatus.statusFailAssignInvalidHandle();
	tools.getStepStatus().set(ProcessingStatus.SEVERITY_FAIL,"Database-Instance-NotFound", "Missing Handle");

} else if (strAssignHandle.startsWith("ASSIGN-INTERNAL")) {

	// No need to open the assignment at this point, we are just executing a case or stage-wide local action
	ClipboardPage assignmentPage = tools.createPage("Assign-Internal", "");

	// Handles are like ASSIGN-INTERNAL PEGASAMPLE C-131!PZINTERNALSTAGEFLOW
	// The flow name should be after the exclamation mark
	int space = strAssignHandle.indexOf(' ')+1;
	int bang = strAssignHandle.indexOf('!');
	String workobjecthandle = strAssignHandle.substring(space, bang);
	String ucaseflowName = strAssignHandle.substring(bang + 1);

	assignmentPage.putString(".pxRefObjectKey", workobjecthandle);
	if (ucaseflowName.equals("PZINTERNALSTAGEFLOW"))
		assignmentPage.putString(".pxFlowName", "pzInternalStageFlow");
	else if (ucaseflowName.equals("PZINTERNALCASEFLOW"))
		assignmentPage.putString(".pxFlowName", "pzInternalCaseFlow");	
	else if (ucaseflowName.equals("PZINTERNALPROCESSFLOW"))
		assignmentPage.putString(".pxFlowName", "pzInternalProcessFlow");	
  	else if (ucaseflowName.equals("OVERALLSLA"))
		assignmentPage.putString(".pxFlowName", "OverallSLA");	
	else
		assignmentPage.putString(".pxFlowName", ucaseflowName);

	myStepPage = pega.setStepPage(tools.getParamValue("assignPage"), assignmentPage);
} else
{
	try
	{
		// Open the assignment without security, since we don't test open security until the
		// the work object is open in OpenAndLockWork
		ClipboardPage assignmentPage = tools.getDatabase().open(strAssignHandle, false);
		if (assignmentPage != null)
		{
			myStepPage = pega.setStepPage(tools.getParamValue("assignPage"), assignmentPage);
		}
		else
		{
			tools.getStepStatus().set(ProcessingStatus.SEVERITY_FAIL,"Database-Instance-NotFound", strAssignHandle);

			// Parse the InsHandle parameter to determine what the problem might be
			int space = strAssignHandle.indexOf(' ')+1;
			int bang = strAssignHandle.indexOf('!');

			if ((space > 0) && (bang > -1))
			{
				// Handles are like ASSIGN-WORKLIST PEGASAMPLE C-131!NEWWORK
				// The flow name should be after the exclamation mark
				String ucaseflowName = strAssignHandle.substring(bang + 1);
				if (ucaseflowName.length() > 0)
				{
					errorMessage = tools.getStepStatus().getWorstMessage();
					status = pega_procom_processenginestatus.statusFailAssignOpen();
				}
				else
				{
					errorMessage = "ProblemAssignment_InvalidAssignmentHandle\t" + strAssignHandle;
					status = pega_procom_processenginestatus.statusFailAssignInvalidHandle();
				}
			}
			else
			{
				errorMessage = "ProblemAssignment_InvalidAssignmentHandle\t" + strAssignHandle;
				status = pega_procom_processenginestatus.statusFailAssignInvalidHandle();
			}
		}
	} catch (DatabaseException de) {
		errorMessage = de.getMessage();
		stackTrace = pega_rules_utilities.getStackTrace(de);
		status = pega_procom_processenginestatus.statusFailAssignInvalidHandle();
		oLog.error(de);
		tools.getStepStatus().set(ProcessingStatus.SEVERITY_FAIL, errorMessage, "");
	}
}

try{
ClipboardPage workPage = tools.getDatabase().open(tools.findPage("assignPage").getString("pxRefObjectKey"), false);
if(workPage != null)
  myStepPage = pega.setStepPage(tools.getParamValue("workPage"), workPage);
}catch(Exception e){
  //do nothing for now
}

String errType = "";
int nSuccess = tools.getParamAsInteger(PropertyInfo.TYPE_INTEGER, "SuccessIndicator");
switch (nSuccess) {
	case -1:
		// unable to open work object
		errType = "Work Open";
		break;
	case -2:
		// work object open access denied
		errType = "Security";
		break;
	case -3:
		// unable to lock work object
		errType = "Locked";
		break;
	case -4:
		// unable to lock work object due to security access
		errType = "Security";
		break;						
	case -5:
		// unable to open cover object
		errType = "Cover Open";						
		break;
	case -6:
		// cover object open access denied
		errType = "Security";
		break;					
	case -7:
		// unable to lock cover object
		errType = "Locked";
		break;
	case -8:
		// unable to lock cover object due to security access
		errType = "Security";
		break;												
	case -9:
		// unable to lock object specified in lock string
		errType = "Locked";
		break;
	case -10:
		// miscellaneous error, since the error could have occurred during locking
		errType = "Exception";
		break;
	case -21:
		// assignment specifies different task than flow
		errType = "Flow Not At Task";
		break;
	case -22:
		// assignment specifies flow page that isn't on work object
		errType = "Flow Removed";
		break;
	case -23:
		// pxAssignmentKey in flow doesn't point to this assignment
		errType = "Assign Mismatch";
		break;
	case -24:
		// Rule-Obj-Flow is gone
		errType = "Rule-Obj-Flow Not Found";
		break;
	case -25:
		// Rule-Obj-Flow is there, but this particular assignment shape is not
		errType = "Assign Task Deleted";
		break;	
	case -26:
		// Assignment's pxFlowName property is blank
		errType = "Assign FlowName Blank";	
		break;		
	case -27:
		// Perform assignment security failed
		errType = "Security";
		break;
	case -28:
		// Assignment already completed
		errType = "Assignment Completed";
		break;
	default:
		errType = "Exception";
		break;
}

// If the error is not because the object is locked or the user does not
// have the security to do what he is attempting to do, 
// or the database assignment is not the same as the one opened prior to locking the work,
//mark this as a problem assignment
if (!errType.equals("Locked") && !errType.equals("Security") && ! errType.equals("Assignment Completed"))
{
	String errMessage = tools.getParamValue("FailureInfo");
	String errMsgDesc = tools.getParamValue("FailureMsgDesc");
	if (!errMsgDesc.equals(""))
		errMessage = errMsgDesc;
	pega_procom_pegaprocomutilities.markProblemAssignment(myStepPage, errType, errMessage, tools);
}
